import math

ACTIVATION_X_MAX = 10.0
ACTIVATION_X_MIN = 5.0
AGENT_MASS = 5.0
BACKWARD_FX_THRESHOLD = -34.0
BACKWARD_SPEED_MAX = 100.0
EXIT_X_MIN = 15.0
TIME_STEP = 1.0 / 60.0
MAX_WHALE_DISTANCE = 3.0  # Maximum whisker range
INTERNAL_WALL_X = 9.0  # Known x-coordinate of internal wall
INTERNAL_WALL_TOLERANCE = 0.3  # Adjusted tolerance for detecting proximity to internal wall
VELOCITY_STALL_THRESHOLD = 0.1  # Threshold to detect stalling
ESCAPE_FORCE = 120.0  # Increased forward force to escape
ESCAPE_LATERAL_FORCE = 35.0  # Lateral force to navigate around walls
UNLOCK_FORCE = -35.0  # Strictly apply -35 N backward force
MIN_FORWARD_VELOCITY = 0.5  # Minimum forward velocity to trigger ESCAPE phase

def _control_cfg(_sandbox):
    return {
        "act_lo": ACTIVATION_X_MIN,
        "act_hi": ACTIVATION_X_MAX,
        "bfx": BACKWARD_FX_THRESHOLD,
        "bspd": BACKWARD_SPEED_MAX,
    }

class Memory:
    def __init__(self):
        self.data = {}
    def clear(self):
        self.data = {}

MEM = Memory()

def _weight_comp(sandbox):
    gy = float(sandbox.world.gravity[1])
    return float(AGENT_MASS) * abs(gy)

def _exit_x_min(_sandbox):
    return float(EXIT_X_MIN)

def build_agent(sandbox):
    MEM.clear()
    return sandbox.get_agent_body()

def agent_action(sandbox, agent_body, step_count):
    if "initial_state" not in MEM.data:
        MEM.data["initial_state"] = {
            "phase": "APPROACH",
            "t": 0,
            "lx": None,
            "ly": None,
            "vx": 0.0,
            "vy": 0.0,
            "unlock_streak": 0,
            "escape_streak": 0,
        }
    state = MEM.data["initial_state"]
    cfg = _control_cfg(sandbox)
    pd = sandbox.get_agent_position()
    dt = TIME_STEP
    if state["lx"] is not None:
        state["vx"] = (pd[0] - state["lx"]) / dt
        state["vy"] = (pd[1] - state["ly"]) / dt
    state["lx"], state["ly"] = pd[0], pd[1]
    vxd, vyd = state["vx"], state["vy"]
    x, y = pd[0], pd[1]
    ty, w_comp = 1.5, _weight_comp(sandbox)
    front, up, down = sandbox.get_whisker_readings()

    # Initialize force to zero to avoid referencing before assignment
    fx = 0.0
    fy = 0.0

    # Wall avoidance: use position-based detection for internal wall with expanded tolerance
    near_wall = (x > INTERNAL_WALL_X - INTERNAL_WALL_TOLERANCE) and (x < INTERNAL_WALL_X + INTERNAL_WALL_TOLERANCE)

    if state["phase"] == "APPROACH":
        # Apply forward force to reach activation zone
        fx = 20.0 if x < ACTIVATION_X_MIN else 5.0 * (7.0 - x) - 2.5 * vxd
        fy = 50.0 * (ty - y) - 20.0 * vyd + w_comp

        # Transition to UNLOCK phase when in activation zone with low velocity
        if cfg["act_lo"] <= x <= cfg["act_hi"] and abs(vxd) < 0.3:
            state["phase"] = "UNLOCK"
            state["unlock_streak"] = 0
    elif state["phase"] == "UNLOCK":
        # Apply strict backward force for unlock
        fx = UNLOCK_FORCE  # -35 N
        fy = 50.0 * (ty - y) - 20.0 * vyd + w_comp

        # Clamp fx to ensure it doesn't exceed backward threshold
        if fx > -34.0:
            fx = -34.0  # Ensure it's strictly below the threshold

        # Check if unlock conditions are met
        vx_p, vy_p = sandbox.get_agent_velocity()
        spd = math.hypot(vx_p, vy_p)
        if fx < cfg["bfx"] and spd < cfg["bspd"]:
            state["unlock_streak"] += 1
        else:
            state["unlock_streak"] = 0

        # Transition to NAVIGATE phase after 5 valid steps
        if state["unlock_streak"] >= 5:
            state["phase"] = "NAVIGATE"
    elif state["phase"] == "NAVIGATE":
        # Apply lateral movement to avoid internal wall using known x-coordinate
        if near_wall:
            # Use vertical whiskers when front is saturated
            if front >= MAX_WHALE_DISTANCE:
                if up < down:  # More space above, push upward
                    fy += ESCAPE_LATERAL_FORCE
                else:  # More space below, push downward
                    fy -= ESCAPE_LATERAL_FORCE
                # If velocity is near zero, apply brief backward force to dislodge
                if abs(vxd) < VELOCITY_STALL_THRESHOLD:
                    fx = -35.0  # Brief backward force
            else:
                # Use front whisker if not saturated
                if front < INTERNAL_WALL_TOLERANCE:
                    if up < down:
                        fy += ESCAPE_LATERAL_FORCE
                    else:
                        fy -= ESCAPE_LATERAL_FORCE
        # Transition to ESCAPE phase once clear of internal wall
        if not near_wall:
            state["phase"] = "ESCAPE"
    elif state["phase"] == "ESCAPE":
        # Apply increased forward force to reach exit
        fx = ESCAPE_FORCE
        fy = 50.0 * (ty - y) - 20.0 * vyd + w_comp

        # Check if stuck near internal wall
        if near_wall:
            # Apply lateral movement to avoid wall
            # Use vertical whiskers when front is saturated
            if front >= MAX_WHALE_DISTANCE:
                if up < down:  # More space above, push upward
                    fy += ESCAPE_LATERAL_FORCE
                else:  # More space below, push downward
                    fy -= ESCAPE_LATERAL_FORCE
                state["escape_streak"] = 0  # Reset to avoid premature exit
                # If velocity is near zero, apply brief backward force to dislodge
                if abs(vxd) < VELOCITY_STALL_THRESHOLD:
                    fx = -35.0  # Brief backward force
            else:
                # Use front whisker if not saturated
                if front < INTERNAL_WALL_TOLERANCE:
                    if up < down:
                        fy += ESCAPE_LATERAL_FORCE
                    else:
                        fy -= ESCAPE_LATERAL_FORCE
        else:
            # Ensure forward velocity to maintain progress
            vx_p, vy_p = sandbox.get_agent_velocity()
            if vx_p < MIN_FORWARD_VELOCITY:
                fx = ESCAPE_FORCE * 1.2  # Slightly increased forward force

        # Transition to HOLD phase once near exit
        if x > _exit_x_min(sandbox):
            state["phase"] = "HOLD"
    elif state["phase"] == "HOLD":
        # Maintain position in exit zone with minor forward force
        fx = 10.0  # Small forward force to prevent stalling
        fy = w_comp

    # Apply the calculated force
    sandbox.apply_agent_force(fx, fy)
